<?php
require_once 'database.php';
$id=(int)($_GET['id']??0); $stmt=$conn->prepare("SELECT * FROM students WHERE id=?"); $stmt->bind_param("i",$id); $stmt->execute(); $student=$stmt->get_result()->fetch_assoc(); if(!$student) die('Student not found.');
if($_SERVER['REQUEST_METHOD']==='POST'){ $sid=trim($_POST['student_id']);$first=trim($_POST['first_name']);$last=trim($_POST['last_name']);$father=trim($_POST['father_name']);$gender=$_POST['gender'];$phone=trim($_POST['phone']);$address=trim($_POST['address']);$class=trim($_POST['class_name']); $u=$conn->prepare("UPDATE students SET student_id=?,first_name=?,last_name=?,father_name=?,gender=?,phone=?,address=?,class_name=? WHERE id=?");$u->bind_param("ssssssssi",$sid,$first,$last,$father,$gender,$phone,$address,$class,$id);$u->execute();header('Location:index.php');exit;}
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Edit Student</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><header><h1>Edit Student</h1></header><nav><a href="index.php">Students</a><a href="add_student.php">Add Student</a></nav><form class="form-card" method="post"><div class="form-grid"><label>Student ID<input name="student_id" required value="<?=htmlspecialchars($student['student_id'])?>"></label><label>First Name<input name="first_name" required value="<?=htmlspecialchars($student['first_name'])?>"></label><label>Last Name<input name="last_name" required value="<?=htmlspecialchars($student['last_name'])?>"></label><label>Father Name<input name="father_name" required value="<?=htmlspecialchars($student['father_name'])?>"></label><label>Gender<select name="gender"><option <?=$student['gender']==='Male'?'selected':''?>>Male</option><option <?=$student['gender']==='Female'?'selected':''?>>Female</option></select></label><label>Phone<input name="phone" value="<?=htmlspecialchars($student['phone'])?>"></label><label>Address<input name="address" value="<?=htmlspecialchars($student['address'])?>"></label><label>Class<input name="class_name" value="<?=htmlspecialchars($student['class_name'])?>"></label></div><button class="button">Update Student</button></form></div></body></html>